package ke.muranga.agriflow;

// Generated by MurangaAgriflow Branding Patch. This screen does not alter HomeScreen.
import android.animation.ValueAnimator;
import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.os.Build;
import android.view.Gravity;
import android.view.View;
import android.view.Window;
import android.view.WindowManager;
import android.view.animation.LinearInterpolator;
import android.widget.FrameLayout;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import java.util.Locale;

/** Branded launch screen with a short, decorative repeating square animation. */
public final class SplashActivity extends Activity {

    private static final long INTRO_DURATION_MS = 5000L;
    private static final long SQUARE_CYCLE_MS = 1250L;
    private final Handler handler = new Handler(Looper.getMainLooper());
    private ValueAnimator squareAnimator;
    private boolean openingMain = false;

    private final Runnable openMainRunnable = new Runnable() {
        @Override
        public void run() {
            if (openingMain || isFinishing()) {
                return;
            }
            openingMain = true;
            startActivity(new Intent(SplashActivity.this, MainActivity.class));
            overridePendingTransition(android.R.anim.fade_in, android.R.anim.fade_out);
            finish();
        }
    };

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS);
        final int brandGreen = getResources().getColor(R.color.agriflow_splash_background);
        final Window window = getWindow();
        window.setStatusBarColor(brandGreen);
        window.setNavigationBarColor(brandGreen);
        int systemUi = window.getDecorView().getSystemUiVisibility();
        if (Build.VERSION.SDK_INT >= 23) {
            systemUi &= ~View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;
        }
        if (Build.VERSION.SDK_INT >= 26) {
            systemUi &= ~View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;
        }
        window.getDecorView().setSystemUiVisibility(systemUi);

        FrameLayout root = new FrameLayout(this);
        root.setBackgroundColor(brandGreen);
        root.setClipChildren(false);
        root.setClipToPadding(false);

        LinearLayout content = new LinearLayout(this);
        content.setOrientation(LinearLayout.VERTICAL);
        content.setGravity(Gravity.CENTER_HORIZONTAL);
        content.setClipChildren(false);
        content.setClipToPadding(false);
        FrameLayout.LayoutParams contentParams = new FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.WRAP_CONTENT,
                Gravity.CENTER
        );
        root.addView(content, contentParams);

        ImageView logo = new ImageView(this);
        logo.setImageResource(R.drawable.agriflow_logo);
        logo.setScaleType(ImageView.ScaleType.FIT_CENTER);
        logo.setContentDescription("Muranga County agricultural technology logo");
        LinearLayout.LayoutParams logoParams = new LinearLayout.LayoutParams(dp(188), dp(188));
        content.addView(logo, logoParams);

        TextView appName = new TextView(this);
        appName.setText(getString(R.string.app_name).toUpperCase(Locale.ROOT));
        appName.setTextColor(Color.WHITE);
        appName.setTextSize(23f);
        appName.setTypeface(Typeface.create("sans-serif-medium", Typeface.BOLD));
        appName.setLetterSpacing(0.055f);
        appName.setGravity(Gravity.CENTER);
        LinearLayout.LayoutParams nameParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        nameParams.setMargins(dp(20), dp(22), dp(20), 0);
        content.addView(appName, nameParams);

        TextView tagline = new TextView(this);
        tagline.setText("COUNTY AGRICULTURE  •  SMARTER FUTURES");
        tagline.setTextColor(Color.argb(220, 235, 247, 235));
        tagline.setTextSize(10.5f);
        tagline.setLetterSpacing(0.12f);
        tagline.setGravity(Gravity.CENTER);
        LinearLayout.LayoutParams taglineParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        taglineParams.setMargins(dp(16), dp(8), dp(16), 0);
        content.addView(tagline, taglineParams);

        LinearLayout squares = new LinearLayout(this);
        squares.setOrientation(LinearLayout.HORIZONTAL);
        squares.setGravity(Gravity.CENTER);
        squares.setClipChildren(false);
        squares.setClipToPadding(false);
        LinearLayout.LayoutParams squaresParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.WRAP_CONTENT, dp(28));
        squaresParams.setMargins(0, dp(38), 0, 0);
        content.addView(squares, squaresParams);

        View[] tiles = new View[3];
        int[] colors = new int[] {
                Color.WHITE,
                Color.rgb(255, 213, 112),
                Color.rgb(210, 242, 219)
        };
        for (int i = 0; i < tiles.length; i++) {
            View tile = new View(this);
            GradientDrawable tileShape = new GradientDrawable();
            tileShape.setShape(GradientDrawable.RECTANGLE);
            tileShape.setColor(colors[i]);
            tileShape.setCornerRadius(dp(2.5f));
            tile.setBackground(tileShape);
            LinearLayout.LayoutParams tileParams = new LinearLayout.LayoutParams(dp(10), dp(10));
            tileParams.setMargins(dp(7), 0, dp(7), 0);
            squares.addView(tile, tileParams);
            tiles[i] = tile;
        }
        squares.setContentDescription("Loading animation");
        setContentView(root);
        startSquareAnimation(tiles);
        handler.postDelayed(openMainRunnable, INTRO_DURATION_MS);
    }

    private void startSquareAnimation(final View[] tiles) {
        squareAnimator = ValueAnimator.ofFloat(0f, (float) (Math.PI * 2.0));
        squareAnimator.setDuration(SQUARE_CYCLE_MS);
        squareAnimator.setRepeatCount(ValueAnimator.INFINITE);
        squareAnimator.setInterpolator(new LinearInterpolator());
        squareAnimator.addUpdateListener(animation -> {
            float phase = (Float) animation.getAnimatedValue();
            for (int i = 0; i < tiles.length; i++) {
                float angle = phase + (float) (i * (Math.PI * 2.0 / tiles.length));
                float wave = (float) Math.sin(angle);
                float scale = 0.70f + ((wave + 1f) * 0.15f);
                tiles[i].setScaleX(scale);
                tiles[i].setScaleY(scale);
                tiles[i].setRotation(wave * 34f);
                tiles[i].setTranslationY(-wave * dp(5));
                tiles[i].setAlpha(0.52f + ((wave + 1f) * 0.22f));
            }
        });
        squareAnimator.start();
    }

    private int dp(float value) {
        return Math.round(value * getResources().getDisplayMetrics().density);
    }

    @Override
    protected void onDestroy() {
        handler.removeCallbacks(openMainRunnable);
        if (squareAnimator != null) {
            squareAnimator.cancel();
            squareAnimator = null;
        }
        super.onDestroy();
    }
}